class Solution { public int numWays(String[] words,String target){final int MOD=1_000_000_007;int length=words[0].length();int[][] count=new int[length][26];for(String word:words)for(int column=0;column<length;column++)count[column][word.charAt(column)-'a']++;long[] dp=new long[target.length()+1];dp[0]=1;for(int column=0;column<length;column++)for(int formed=Math.min(column,target.length()-1);formed>=0;formed--)dp[formed+1]=(dp[formed+1]+dp[formed]*count[column][target.charAt(formed)-'a'])%MOD;return (int)dp[target.length()];} }
